"""Author one explicitly NEW temporary-exile proposal with preserved source limits."""
from datetime import datetime,timezone
from pathlib import Path
import hashlib,json
from apply_di7_ap_as_01 import G,R,A,info,encoded
def read(p):return json.loads(p.read_bytes())

def main():
    root=A/'banishment-local-draft-01';receipt=A/'BANISHMENT_LOCAL_DRAFT_01_PREPARATION.json'
    assert not root.exists() and not receipt.exists()
    catalog=R/'data/public/spell_playtests/catalog.json';source=next(x for x in read(catalog)['spells'] if x['id']=='banishment')
    index=R/'data/public/spell_playtests/authored_review_index.json';entry=next(x for x in read(index)['entries'] if x['id']=='banishment')
    assert source['operational'] is None and entry['procedurePointer'] is None
    paths=[catalog,index,R/'data/playtest/spell_sources/catalog.json',R/'data/public/Decennium_Descent_Core_Systems_Data_v2_Known_Descent.json',
      R/'data/public/class_playtests/cleric.json',R/'data/public/class_playtests/oracle.json',
      R/'docs/mechanics/SPELL_INTEGRATION_RULES.md',R/'docs/mechanics/CLASS_PLAYTEST_RULES.md',R/'docs/mechanics/COMBAT_ACTION_PLAYTEST.md',
      R/'docs/mechanics/CONTROL_STATES_PLAYTEST.md',R/'docs/mechanics/ENCHANTMENT_CONTROL_INTEGRATION_PLAYTEST.md',R/'docs/mechanics/CREATURE_LIFECYCLE_PLAYTEST.md',
      R/'docs/mechanics/BODY_EQUIPMENT_PLAYTEST.md',R/'docs/mechanics/HEALING_DEATH_PLAYTEST.md',R/'docs/mechanics/DAMAGE_SHARING_PLAYTEST.md',
      R/'docs/mechanics/COSMOLOGY_EPILOGUE_RELIC_NULL_PLAYTEST.md',R/'data/director/cosmology/epilogue_relic_null_reviewed_01.json',
      R/'docs/director-only/cosmology/PLANES_REVIEWED_01.md',R/'data/director/cosmology/planes_reviewed_01.json',
      R/'docs/director-only/cosmology/SOULS_RESEARCH_REVIEWED_01.md',R/'docs/director-only/cosmology/HEARTCELL_OWNER_UPDATE_02.md',
      R/'docs/director-only/cosmology/Q6_LATER_LOCK_REVIEWED_01.md',G/'docs/mechanics/OWNER_COSMOLOGY_LOCKS_2026-07-30.md',
      A/'ABJURATION_CONJURATION_RANK4_SOURCE_PREPARATION.json',A/'AC4_CURRENT_REVIEW_01_SUBMISSION_RECEIPT.json',Path(__file__)]
    bindings=[info(p) for p in paths];core=read(paths[3])
    assert source['source']['original']==read(paths[2])['banishment']
    assert source['source']['coreEntries'][0]['original']==core['spells'][48]
    class_refs=[]
    for filename,ident in [('cleric.json','cleric.arch.banish-unholy'),('oracle.json','oracle.supplement.fate-bound.fate-bound-boon-iv')]:
        p=R/'data/public/class_playtests'/filename;cards=read(p)['cards'];i=next(i for i,c in enumerate(cards) if c['id']==ident)
        class_refs.append({'file':info(p),'jsonPointer':f'/cards/{i}','value':cards[i]})
    sections=[
      ('Source and authority','PRESERVED: Abjuration rank4 through each actual access row, base7 RP, Action, 60 feet, V/S/F, and temporarily sending one creature to another plane. Core labels duration Instantaneous and provides no concrete save, exile destination, timer or return method. NEW proposals below supply those missing procedures; none is recovered cosmology, an existing class ability, or approved playtest text. The old wait-for-push sequencing hold is satisfied. Banish Unholy remains a different Cleric technique and grants neither this spell nor its destination/return rules.'),
      ('Casting and target','Choose one actually perceived creature within60 feet and line of effect, including yourself. Use its current body, not an image, corpse or soul record. Actual creature-classified Undead and Constructs remain eligible unless an exact defense applies. Require actual class access/repertoire, V/S/F, Action, ordinary casting affordability, real target geometry and the ordinary cast/counter sequence. NEW concentration starts at legal cast commitment, displacing incompatible prior concentration; maximum exile is60 elapsed seconds from successful resolution. A saved-against, countered or otherwise failed cast keeps paid costs and does not restore prior concentration.'),
      ('Save, hard-control and replacement','NEW target CHA save against the actual casting-class spell DC, binary; an actually willing target may elect failure before rolling. Success produces no exile. Apply real defenses, including an actually acquired Oracle Fate-Bound Boon IV +2 against banishment; Charmed-only immunity does not block an effect imposing no Charmed condition. Treat establishment as one hard encounter-removal component under the shared source-character/target/encounter guard: if that source already spent its guard, no exile occurs and no invented soft effect replaces it. A single continuing application does not spend again each turn. Only one live Banishment application may attach to a creature across casters; an already attached creature is ineligible for another until the first ends, with no replacement, stacked cell or renewed timer. Known illegality prevents commitment; hidden eligibility is adjudicated after commitment without a diagnostic/refund.'),
      ('Explicit proposed destination','NEW bounded spell-space proposal requiring independent GPT cosmology/interface review: successful resolution creates one isolated temporary extraplanar cell distinct from the origin plane, then transports the same target into it. It is not identified with Bastion of Flame, Veiled Expanse, Radiant Currents, Boundless Void, any mortal Great Wheel label, an afterlife, a named god or an unresolved cosmic identity. It establishes no reusable route, recovered world or global plane-creation permission. The cell has a level supporting floor, ordinary light and a breathable environment compatible with the admitted creature; it itself inflicts no temperature/pressure/environmental damage. Existing disease, damage, life states and other hazards attached to the creature continue normally. Floor, walls, light and air are ephemeral spell boundaries, not harvestable stock. Cell dimensions are the target’s actual occupied bounding dimensions plus10feet along each axis, rounded up to5-foot increments, with its initial body centered legally; this supplies5feet of clearance on each side without a source-absent size/type cap. Geometry must be an actual established finite body record, not invented hidden anatomy.'),
      ('Agency and isolation','The target retains its existing condition-limited Actions, Bonus Actions, Reactions, movement and concentration. The banishment itself imposes neither Incapacitated nor stasis. Boundaries prevent mundane passage and ordinary line of sight/effect into another place; there is no native exit or attack path. Independently acquired exact cross-plane information/travel powers retain their actual permissions and costs; the spell creates no knowledge of another destination, receiving headquarters or portal. An actual legal escape leaving the cell ends this Banishment immediately without dragging the escaped identity back. A failed escape spends only its own source-defined costs. No other creature can be admitted through a new Banishment or by calling it cargo; independently legal interplanar entry still needs its actual route, known destination and fitting space, and does not receive a free return entitlement.'),
      ('Clocks, concentration and source ending','NEW this spell uses a fixed absolute deadline of resolution+60elapsed seconds. Traveler time and outside time advance1:1 for this cell only. Extra turns, initiative changes, suppression, travel, death, scene changes and companion control changes do not restart it; no rest/resource benefit is created. Ordinary personal effect durations, concentration checks, HP/Wounds, death saves, Stable recovery, summon expiry, Opening/Horn and Hunt histories continue on their existing clocks. Ending required concentration, actual dispel of this application, actual suppression of this application, or the absolute deadline initiates return and ends the isolation rather than suspending it for later resumption. A caster may end its own concentration through the normal permission. Mere distance or separation onto the cell’s plane does not end this spell. Independent condition/source rules still apply.'),
      ('Transport and real cargo','Transport one creature identity with its actually worn/carried noncreature gear within real carrying and dimensional limits. No second creature travels as gear, including a mount, carried passenger, swallowed separate creature or controlled companion. Before departure establish legal origin placement for any separate carried body that will remain; if that separation is physically impossible, no transport occurs. Do not cut, copy or move an external anchor/fixture merely by calling it inventory: a tethered assembly that cannot be transported intact with this one body prevents that proposed transaction unless another actual rule already permits separation. Known physical impossibility is preflight failure; hidden or intervening impossibility defeats the paid transport without refund. This is an explicit NEW atomic-transport limit to be reviewed, not a claim that mundane restraints universally block other teleports. Record every actual transported object, its custody and its physical location. Objects used/consumed/ended inside follow their own rules; no replacement appears on return.'),
      ('Return anchor and early-return proposal','NEW finite-return mechanism requiring explicit review: preserve the exact legal origin footprint/orientation and height as the return anchor; it does not move with the caster, an origin vehicle or a later map view. There is no force-wall reservation. Before an actual event would make that footprint illegal for the target’s then-current returning body, end this banishment and return it to the still-legal anchor first, then continue that event under ordinary rules. This includes another body/object entering the anchor, terrain/support changes, and a target body/gear transformation that would no longer fit the anchor or cell. The early return occurs at the event’s real resolution boundary, before the geometry changes, never rewinds a completed atomic damage/life event and never cancels committed costs. After return, the event can affect the target normally; ordinary movement may stop because a returned body now occupies its intended destination. This is a scoped NEW spell behavior, not a universal preemptive-trigger system or a source of remote information. A support-loss event returns the creature before loss and then ordinary Falling applies; a plane-destruction event does not grant immunity. No knowingly invalid origin anchor may be accepted at casting.'),
      ('Return transaction and exceptional collision','At ordinary early ending/deadline, place the same current target body at its recorded still-legal anchor once, with the gear actually still carried. Do not create a new body, refresh HP or move a creature that already escaped independently. If true death occurred, return the same surviving corpse; Hunt/return-from-death law is unchanged because moving a corpse is not resurrection. If an independent source actually removed the body, return no substitute. Existing noncreature objects left in the cell return once to the anchor’s floor in their recorded stable object-ID order, using actual nearest legal placements for loose objects without embedding or duplicating them; items already taken out are absent from that list. A separately arrived creature has no automatic return grant and prevents final collapse while physically present; that unresolved exceptional occupancy requires the exact entry source’s exit/return procedure. This last interaction is explicitly unresolved for review, not permission to strand or delete a body. If a supplied effect makes the anchor illegal without the proposed pre-resolution return window, do not improvise crushing, eviction, duplication or an indefinite denied turn: record the actual collision and resolve an explicit joint-review completion before this draft can be adopted.'),
      ('Current spell and relic interfaces','Counterspell acts only during legal cast windows. A minimum-rank4 Banishment does not qualify for the pending rank0–3 Spell Shield merely because its RP was discounted. Dimensional Anchor is currently in the separate AC4 review; its proposed endpoint prevention is comparison evidence until accepted, not an existing approved source. A real applicable transport block at either endpoint defeats travel under its own rule; it never produces partial cargo. Xi can end only this ongoing spell’s eligible creature target branch with actual caster/target consent, perception, range, Action and charge; there is no general remote release from merely possessing the pendant. Source owner, target, damage dealer and transport identity remain separate. Return itself causes no attack/damage/healing, and the spell grants no alignment change, oath exception, permanent exile, origin-plane diagnosis or immunity to Hunted Death.')]
    questions=[
      {'id':'BAN-01','question':'Does the scoped generated extraplanar cell preserve the original temporary-other-plane effect without adopting forbidden cosmological identities? Accept/revise its exact local topology; do not assert it is recovered canon.'},
      {'id':'BAN-02','question':'Confirm the proposed concentration60s/CHA save, willing-failure permission, one-live-application rule and shared hard-control use against actual class/source scope.'},
      {'id':'BAN-03','question':'Resolve the return mechanism completely. Is early return before origin/body geometry change coherent with actual atomic event boundaries and transport prevention? Replace exact operations where needed; no indefinite hard-denial extension, crushing or silently suppressed costs.'},
      {'id':'BAN-04','question':'Complete independently legal interplanar entry and escape, residual cargo and cell collapse. The draft flags exceptional visitors and uninterruptible anchor changes rather than silently stranding/deleting them; a full runnable resolution is required before approval.'},
      {'id':'BAN-05','question':'Confirm one-body transport, carried creatures, swallowed separate bodies, mounts, tethers, custody, transformations, true death/body removal and Null-disabled summons without rewriting other teleport or lifecycle rules.'},
      {'id':'BAN-06','question':'Use current accepted AC4 outcomes when available for Anchor/Shield/Beacon integration, and preserve actual Oracle/Cleric/Xi distinctions. No generic resistance, saved-score migration, lore revelation or control immunity may be inferred.'}]
    examples=[
      ('BAN-C01','Wizard7,INT+4,PB3,actual spell prepared,RP30,precast strain below surcharge; target CHA total14 vsDC15, no defenses/guard use, origin legal.','Commit7RP and current ordinary strain/concentration; on failure create one cell and target branch at t0, with deadline t60. No attack or damage.'),
      ('BAN-C02','Same state, target CHA total15.','Save succeeds; no cell/transport/hard component. RP and cast strain remain spent; displaced prior concentration is not restored.'),
      ('BAN-C03','Target actually has Oracle15 Fate-Bound BoonIV; ordinary CHA total13,DC15.','Actual+2 banishment bonus gives15 and succeeds, subject to the existing strongest-flat-bonus rule. No generic protection for other Oracle paths.'),
      ('BAN-C04','Source previously used a hard whole-turn component on this target in the encounter; target would fail CHA.','No new exile, no replacement soft effect and no refunded cast. A fresh session label does not erase the same encounter record.'),
      ('BAN-C05','Exile begins t0; target is still present at t60; anchor is legal.','Return same body/actual carried gear once at t60. No renewed turn, HP, resources, deadline or short/long rest.'),
      ('BAN-C06','At t18 another creature starts a movement step whose completion would occupy the anchor.','Proposed rule returns the banished body immediately before that geometry change; resolve ordinary occupied-space movement. No force-wall damage or duplicate body. Requires BAN-03 confirmation.'),
      ('BAN-C07','At t24 an actual effect would remove the origin platform’s support.','Proposed rule returns the target before support loss; support then fails and ordinary Falling starts. Banishment grants no fall immunity. Requires BAN-03 confirmation.'),
      ('BAN-C08','A finite summon takes qualifying Null damage inside at t12 and reaches0; its own source expires t30.','Use current Null Disabled instead of damage-caused disappearance at t12. Independent source expiry at t30 removes that body; Banishment returns no replacement body or loot. Real loose cargo remains recorded.'),
      ('BAN-C09','Hunted target suffers a complete fatal event inside at t20, with all legitimate replacements resolved and no survival.','Commit actual Hunted Death; return only the surviving corpse at spell ending. The transportation does not revive, duplicate or free its soul.'),
      ('BAN-C10','Target voluntarily leaves the cell through an independently legal cross-plane Faction Portal with actual HQ knowledge/standing/source permission.','Use that real route, payment, custody and destination. End this Banishment without pulling the escaped identity back; return only objects still in the cell. No HQ knowledge is supplied by Banishment.'),
      ('BAN-C11','An actual different creature enters through an independently legal route before ending.','Draft requires BAN-04 completion; no automatic inclusion as cargo, body deletion or unsupported claim that independent interplanar travel is universally blocked.'),
      ('BAN-C12','Target carries a separate willing ally and a real backpack.','Only chosen body and legal noncreature gear can depart. Establish legal origin placement for the ally; impossible separation defeats the atomic transaction. No free second traveler.'),
      ('BAN-C13','At t25 target’s real shapechange would exceed original anchor dimensions.','Proposed rule returns the current pre-change body first, then resolves the paid shapechange under its actual placement rules. It grants no free resize or transformation refund; BAN-03 must confirm event ordering.'),
      ('BAN-C14','Caster ends concentration t9 while target is legal; later the original ward returns from suppression.','Return at t9 and terminate this application; restoration does not re-banish or revive its old timer.'),
      ('BAN-C15','A genuine endpoint transport prohibition arises during exile.','BAN-03/06 must explicitly reconcile prevention with early/mandatory return and finite temporary duration; the draft claims no universal bypass or indefinite prison.'),
      ('BAN-C16','A corpse is selected as the original target; an actual active creature-classified Undead is selected in another cast.','Corpse is not an eligible creature. Active Undead is not excluded by its name; actual creature/type defenses and source eligibility govern.'),
      ('BAN-C17','Origin and target remain stable; countered cast, hidden later obstruction, and actual target save reroll occur in separate fixtures.','Preserve chronological payment/cadence and original saves; no new target, free retry or refund. Exact numeric outcomes must be supplied in later joint review.'),
      ('BAN-C18','Target drops an originally transported sword inside, consumes a real potion and later returns.','Return the same surviving sword and empty surviving container where actually present, never an unconsumed potion or duplicate carried item. Ending creates no material from cell walls/air/floor.')]
    payload={'id':'BANISHMENT-LOCAL-DRAFT-01','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'UNSUBMITTED, UNADOPTED NEW proposal with explicit unresolved return/visitor interfaces; not a complete approved procedure.',
      'sourceCard':source,'currentAuthoredIndexEntry':entry,'exactClassComparisons':class_refs,'sections':[{'title':t,'text':v} for t,v in sections],
      'reviewQuestions':questions,'examples':[{'id':i,'initialState':s,'proposedOutcome':o,'evidenceKind':'authored conditional example; unresolved outcomes explicitly marked, not runtime or human test'} for i,s,o in examples],
      'sourceBindings':bindings,'sequenceHoldSatisfied':True,'newRulesAdopted':False,'sourceInformationDeleted':0,'runtimeTestsExecuted':0,'humanPlaytested':False}
    root.mkdir();(root/'PROPOSAL.json').write_bytes(encoded(payload));(root/'SOURCE_BINDINGS.json').write_bytes(encoded(bindings))
    text='# Banishment — local authoring draft\n\nUNSUBMITTED AND UNADOPTED. This draft deliberately marks unresolved return, visitor and transport-block interactions; it is not a selectable spell or approved cosmology.\n\n'
    text+='\n\n'.join('## '+t+'\n\n'+v for t,v in sections)
    text+='\n\n## Questions requiring actual joint review\n\n'+'\n\n'.join('**'+q['id']+'** '+q['question'] for q in questions)+'\n'
    (root/'PROCEDURE_DISCUSSION.md').write_text(text,encoding='utf8',newline='\n')
    (root/'AUTHORED_EXAMPLES.json').write_bytes(encoded(payload['examples']))
    assert all(info(p)==b for p,b in zip(paths,bindings))
    receipt.write_bytes(encoded({'recordedAtUtc':payload['recordedAtUtc'],'proposal':info(root/'PROPOSAL.json'),'discussion':info(root/'PROCEDURE_DISCUSSION.md'),'examples':info(root/'AUTHORED_EXAMPLES.json'),'sourceBindings':info(root/'SOURCE_BINDINGS.json'),'sourceCount':len(bindings),'sourceBytesUnchanged':True,'exactClassComparisons':len(class_refs),'authoredExamples':18,'unresolvedReviewQuestions':6,'fullyRunnable':False,'submitted':False,'newRulesAdopted':False,'sourceInformationDeleted':0,'runtimeTestsExecuted':0}))
    print(json.dumps({'receipt':info(receipt),'sources':len(bindings),'examples':18,'questions':6,'adopted':False}))

if __name__=='__main__':main()
